  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, status, attribution_type, created_by, updated_by, creator_principal_id)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $bq$Masalah: Komputer Hang dan Aplikasi Tidak Merespons$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $bq$Komputer tiba-tiba melambat, kursor berputar-putar, dan aplikasi menampilkan pesan "Not Responding" adalah masalah umum yang dialami pengguna Windows. Penyebabnya bisa beragam: aplikasi yang macet, memori (RAM) penuh, disk 100 persen, atau terlalu banyak program berjalan di latar belakang. Tanpa alat yang tepat, banyak orang langsung mematikan komputer dengan menekan tombol power — cara yang berisiko merusak data dan sistem. Task Manager adalah utilitas bawaan Windows untuk memantau dan mengelola proses yang berjalan: ia menampilkan aplikasi dan layanan yang aktif, seberapa besar CPU, memori, disk, dan jaringan yang mereka gunakan, serta memungkinkan kita menghentikan proses yang bermasalah — semuanya tanpa menginstal apapun.$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $bq$Persiapan Alat yang Dibutuhkan$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 3, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Komputer Windows 10 atau 11 yang masih bisa menyala$txt$, $txt$Keyboard (untuk kombinasi tombol Ctrl + Shift + Esc)$txt$, $txt$Sedikit kesabaran — jangan panik saat komputer melambat$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $bq$Langkah 1: Buka Task Manager dan Hentikan Aplikasi yang Macet$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Tekan Ctrl + Shift + Esc secara bersamaan — ini cara tercepat. Jika tidak berhasil, tekan Ctrl + Alt + Del lalu pilih Task Manager.$txt$, $txt$Saat pertama dibuka, klik "More details" (tanda panah ke bawah) untuk melihat tampilan lengkap.$txt$, $txt$Pada tab Processes, cari aplikasi berlabel "Not Responding", klik kanan, lalu pilih "End task".$txt$, $txt$Peringatan: jangan sembarang menghentikan proses sistem seperti svchost.exe atau csrss.exe — itu bisa membuat komputer restart sendiri.$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $bq$Langkah 2: Analisis Penyebabnya$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Perhatikan kolom CPU, Memory, Disk, dan Network — kolom berwarna gelap menandakan pemakaian tinggi.$txt$, $txt$Jika Disk selalu 100 persen, kemungkinan penyebabnya adalah hard disk tua atau antivirus sedang memindai.$txt$, $txt$Jika Memory mendekati penuh, tutup aplikasi yang tidak dipakai atau pertimbangkan menambah RAM.$txt$, $txt$Pada tab Startup, nonaktifkan program yang tidak perlu berjalan otomatis saat komputer dinyalakan (klik kanan → Disable).$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $bq$Risiko dan Batasan$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $bq$Menghentikan proses yang sedang menyimpan data bisa membuat file menjadi rusak — simpan pekerjaan secara berkala agar tidak kehilangan progres. Mengakhiri proses sistem penting bisa menyebabkan Windows tidak stabil, layar biru, atau restart mendadak. Task Manager juga tidak bisa memperbaiki kerusakan hardware atau malware yang sudah terlanjur menyebar; itu butuh langkah lanjutan seperti pemindaian antivirus atau bantuan teknisi.$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $bq$Pemeriksaan Hasil dan Tindak Lanjut$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $bq$Setelah aplikasi yang macet dihentikan, komputer seharusnya kembali responsif. Verifikasi dengan memeriksa tab Performance: pastikan CPU, memori, dan disk berada di bawah 80 persen saat pemakaian normal. Jika komputer tetap sering hang, lakukan tindak lanjut: bersihkan file sementara dengan Disk Cleanup, perbarui driver dan Windows, pindai malware, dan jika masalah berulang pada hard disk, pertimbangkan mengganti ke SSD. Untuk masalah yang tidak teratasi, catat pesan error yang muncul lalu konsultasikan ke teknisi atau komunitas pengguna Windows.$bq$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, status, attribution_type, created_by, updated_by, creator_principal_id)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $bq$Masalah: Hidung Tersumbat yang Mengganggu$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $bq$Hidung tersumbat membuat bernapas tidak lega, suara bindeng, tidur terganggu, dan konsentrasi menurun. Kondisi ini bisa muncul saat flu, alergi, perubahan cuaca, atau paparan debu dan asap. Pada kebanyakan kasus, hidung tersumbat bersifat ringan dan bisa diredakan dengan perawatan mandiri di rumah. Hidung tersumbat umumnya terjadi karena pembengkakan pembuluh darah dan jaringan di dalam hidung akibat peradangan, atau karena lendir (ingus) yang menumpuk — saat pilek, tubuh memproduksi lebih banyak lendir untuk melawan infeksi; saat alergi, pemicu seperti debu atau serbuk sari memicu peradangan. Artikel ini memberikan informasi umum tentang cara meredakannya dan kapan Anda perlu berkonsultasi ke dokter.$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $bq$Persiapan yang Dibutuhkan$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 3, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Air minum hangat yang cukup$txt$, $txt$Handuk bersih dan baskom berisi air hangat (untuk uap)$txt$, $txt$Cairan saline hidung atau semprotan garam (bisa dibeli di apotek)$txt$, $txt$Tisu yang lembut dan tidak berpewangi$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $bq$Langkah 1: Uap Hangat dan Hidrasi$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Minum air hangat secara rutin agar lendir lebih encer dan mudah keluar.$txt$, $txt$Hirup uap dari baskom air hangat: tundukkan wajah di atas baskom dengan jarak aman sekitar 30 cm, tutup kepala dengan handuk, hirup perlahan selama 5–10 menit.$txt$, $txt$Hati-hati dengan air yang terlalu panas agar kulit tidak terbakar.$txt$, $txt$Semprotkan saline ke hidung sesuai petunjuk kemasan untuk melembapkan rongga hidung.$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $bq$Langkah 2: Atur Lingkungan dan Posisi$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Tidur dengan posisi kepala sedikit lebih tinggi (sangga bantal) agar lendir tidak menumpuk.$txt$, $txt$Hindari pemicu seperti asap rokok, debu, dan wewangian kuat.$txt$, $txt$Jaga kebersihan kamar dan cuci sprei secara rutin jika Anda punya riwayat alergi.$txt$, $txt$Keluarkan ingus dengan lembut satu sisi bergantian — jangan meniup terlalu keras karena bisa menekan saluran telinga.$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $bq$Risiko: Penggunaan Obat Dekongestan Sembarangan$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $bq$Semprotan hidung dekongestan yang dijual bebas bisa melegakan dengan cepat, tetapi penggunaannya lebih dari tiga hari berturut-turut berisiko menimbulkan efek rebound — hidung justru semakin tersumbat setelah obat berhenti. Jangan berbagi semprotan hidung dengan orang lain. Untuk anak-anak, ibu hamil, dan penderita tekanan darah tinggi atau penyakit jantung, konsultasikan dulu ke dokter atau apoteker sebelum memakai obat apapun.$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $bq$Kapan Harus Konsultasi ke Dokter$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $bq$Informasi ini bersifat umum dan bukan pengganti nasihat medis profesional. Segera konsultasikan ke dokter jika: hidung tersumbat lebih dari 10 hari tanpa perbaikan; disertai demam tinggi, nyeri wajah berat, atau ingus berwarna kuning kehijauan yang tidak kunjung membaik; ada darah dari hidung yang sulit berhenti; bayi sulit menyusu karena hidung tersumbat; atau tersumbat setelah cedera wajah. Jika Anda ragu, pilihan paling aman adalah memeriksakan diri ke fasilitas kesehatan terdekat.$bq$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, status, attribution_type, created_by, updated_by, creator_principal_id)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $bq$Siapa Suku Sasak$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $bq$Suku Sasak adalah kelompok etnis asli Pulau Lombok, Nusa Tenggara Barat, dan menjadi mayoritas penduduk di sana. Mereka berbicara bahasa Sasak, memiliki adat yang kaya, dan mayoritas memeluk agama Islam dengan akulturasi tradisi lokal yang masih hidup. Salah satu tradisi paling terkenal mereka adalah Bau Nyale, ritual tahunan menangkap cacing laut yang menarik ribuan orang.$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $bq$Legenda Putri Mandalika$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $bq$Bau Nyale berakar pada legenda Putri Mandalika, seorang putri kerajaan yang cantik dan bijaksana. Konon, banyak pangeran melamarnya dan ia khawatir penolakannya akan menimbulkan perang antar kerajaan. Demi kedamaian, sang putri memilih menceburkan diri ke laut selatan Lombok. Tubuhnya kemudian berubah menjadi cacing laut berwarna-warni yang disebut nyale — simbol pengorbanan dan cinta kasih.$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $bq$Ritual Bau Nyale$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $bq$Setiap tahun pada bulan kesepuluh penanggalan Sasak (sekitar Februari–Maret), masyarakat berkumpul di Pantai Seger, Kuta, Lombok, untuk menangkap nyale yang muncul di perairan dangkal. Ritual ini diawali dengan upacara adat dan doa, lalu para peserta — tua, muda, laki-laki, perempuan — turun ke laut menangkap cacing dengan tangan atau alat sederhana. Nyale kemudian dimasak menjadi berbagai hidangan dan disantap bersama.$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $bq$Makna Sosial dan Budaya$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $bq$Bau Nyale bukan sekadar menangkap cacing; ia adalah perayaan kebersamaan, syukur atas hasil laut, dan pengingat akan nilai pengorbanan Putri Mandalika. Tradisi ini mempertemukan masyarakat dari berbagai desa, memperkuat ikatan sosial, dan menjadi media pewarisan nilai budaya kepada generasi muda. Kini Bau Nyale juga menjadi magnet wisata budaya Lombok yang dikenal luas.$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $bq$Melestarikan Tradisi di Tengah Modernisasi$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $bq$Seperti banyak tradisi di Indonesia, Bau Nyale menghadapi tantangan zaman: generasi muda yang merantau, komersialisasi wisata, dan perubahan lingkungan laut. Upaya pelestarian dilakukan melalui festival budaya, pendidikan adat di sekolah, dan keterlibatan pemerintah daerah. Tradisi yang tetap hidup menunjukkan bahwa kearifan lokal bisa berdampingan dengan kemajuan — selama masyarakatnya merasa memiliki dan bangga terhadapnya.$bq$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, status, attribution_type, created_by, updated_by, creator_principal_id)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $bq$Aluminium di Sekitar Kita$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $bq$Aluminium (simbol kimia Al, nomor atom 13) adalah logam ringan berwarna keperakan yang ada di mana-mana: badan pesawat, rangka sepeda, kaleng minuman, foil dapur, hingga kabel listrik. Ia merupakan logam paling melimpah di kerak bumi (sekitar 8 persen), namun baru bisa diproduksi secara massal setelah metode elektrolisis ditemukan pada akhir abad ke-19.$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $bq$Sifat-Sifat Khas Aluminium$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $bq$Aluminium memiliki massa jenis hanya sekitar 2,7 gram per sentimeter kubik — sekitar sepertiga dari baja — sehingga ideal untuk aplikasi yang menuntut ringan namun kuat. Ia tahan korosi karena membentuk lapisan oksida pelindung yang tipis di permukaannya, menghantarkan panas dan listrik dengan baik, tidak bersifat magnetis, serta mudah dibentuk (ulet dan dapat ditempa). Titik leburnya sekitar 660 derajat Celsius.$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $bq$Dari Bauksit Menjadi Logam$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $bq$Aluminium tidak ditemukan sebagai logam murni di alam; ia diekstrak dari bijih bauksit. Prosesnya melalui dua tahap besar: pertama, bauksit dimurnikan menjadi alumina (aluminium oksida) lewat proses Bayer; kedua, alumina dileburkan dan dielektrolisis dalam proses Hall-Héroult untuk menghasilkan aluminium murni. Proses elektrolisis ini membutuhkan energi listrik yang sangat besar, sehingga pabrik aluminium biasanya berada dekat sumber listrik murah.$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $bq$Kegunaan dalam Kehidupan Modern$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $bq$Kombinasi ringan, kuat, dan tahan korosi membuat aluminium tak tergantikan di banyak bidang. Industri penerbangan menggunakannya untuk badan pesawat; industri otomotif untuk pelek dan komponen mesin; industri kemasan untuk kaleng minuman dan foil; industri konstruksi untuk kusen dan fasad; dan industri listrik untuk kabel transmisi. Paduan aluminium (misalnya dengan tembaga atau magnesium) menghasilkan material yang lebih kuat untuk kebutuhan khusus.$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $bq$Daur Ulang: Keunggulan Terbesar$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $bq$Salah satu keunggulan terbesar aluminium adalah ia dapat didaur ulang berulang kali tanpa kehilangan kualitas. Daur ulang aluminium hanya membutuhkan sekitar 5 persen dari energi yang diperlukan untuk memproduksi aluminium baru dari bauksit. Karena itu, kaleng minuman bekas sangat bernilai untuk didaur ulang. Indonesia sendiri memiliki cadangan bauksit yang besar, sehingga pengelolaan bijih dan industri aluminium menjadi isu strategis nasional.$bq$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, status, attribution_type, created_by, updated_by, creator_principal_id)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $bq$Tujuan Pembelajaran$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $bq$Setelah mempelajari materi ini, peserta didik diharapkan mampu: (1) mengidentifikasi ungkapan greeting dan leave taking dalam bahasa Inggris; (2) membedakan sapaan formal dan informal sesuai situasi; (3) menggunakan ungkapan sapaan dan pamit dalam dialog sederhana; (4) merespons sapaan dan pamit dengan tepat.$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $bq$Greeting (Sapaan)$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $bq$Greeting adalah ungkapan yang digunakan untuk menyapa seseorang saat bertemu. Sapaan dalam bahasa Inggris dibedakan menjadi formal (resmi) dan informal (santai). Pilihan sapaan bergantung pada siapa lawan bicara kita: orang yang lebih tua, guru, atau orang asing menggunakan sapaan formal; teman sebaya atau keluarga menggunakan sapaan informal.$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 4, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Formal: Good morning, Good afternoon, Good evening, How do you do?$txt$, $txt$Informal: Hi, Hello, Hey, What's up?, How's it going?$txt$, $txt$Respon: I'm fine, thank you. / I'm doing well. / Not bad, thanks.$txt$, $txt$Sapaan berdasarkan waktu: Good morning (pagi), Good afternoon (siang), Good evening (sore/malam).$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 5, jsonb_build_object('text', $bq$Leave Taking (Pamit)$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 6, jsonb_build_object('text', $bq$Leave taking adalah ungkapan yang digunakan saat berpamitan atau berpisah dengan seseorang. Sama seperti greeting, ungkapan pamit juga ada yang formal dan informal. Selain mengucapkan pamit, biasanya disertai harapan atau doa baik untuk lawan bicara.$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Formal: Goodbye, Farewell, It was nice meeting you, Have a nice day.$txt$, $txt$Informal: Bye, Bye-bye, See you later, See you tomorrow, Take care.$txt$, $txt$Respon: Goodbye. / See you. / You too.$txt$, $txt$Ungkapan harapan: Have a good trip! / Good luck! / Enjoy your holiday!$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $bq$Contoh Dialog$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $bq$Dialog sapaan di sekolah: Andi: "Good morning, Mrs. Rina!" Mrs. Rina: "Good morning, Andi. How are you today?" Andi: "I'm fine, thank you. And you?" Mrs. Rina: "I'm well, thank you." — Dialog pamit: Budi: "Well, I have to go now. See you tomorrow!" Dina: "Okay, take care. Bye!" Budi: "Bye!"$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $bq$Latihan Soal dan Kunci Jawaban$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Latihan 1: Tuliskan tiga contoh sapaan formal dalam bahasa Inggris.$txt$, $txt$Latihan 2: Apa perbedaan sapaan formal dan informal? Berikan masing-masing satu contoh situasi.$txt$, $txt$Latihan 3: Respon yang tepat untuk sapaan "How are you?" adalah ....$txt$, $txt$Latihan 4: Tuliskan dialog pamit singkat antara dua orang teman.$txt$, $txt$Latihan 5: "Have a nice day!" termasuk ungkapan greeting atau leave taking? Jelaskan.$txt$, $txt$Kunci 1: Good morning, Good afternoon, Good evening (atau How do you do?).$txt$, $txt$Kunci 2: Formal untuk situasi resmi/orang yang dihormati (contoh: Good morning, Sir); informal untuk teman/keluarga (contoh: Hi / Hey).$txt$, $txt$Kunci 3: I'm fine, thank you. (atau I'm doing well.)$txt$, $txt$Kunci 4: Contoh — A: "I have to go home now. See you!" B: "Okay, take care. Bye!"$txt$, $txt$Kunci 5: Leave taking — diucapkan saat berpamitan/berpisah.$txt$])));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, status, attribution_type, created_by, updated_by, creator_principal_id)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $bq$Tujuan Pembelajaran$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $bq$Setelah mempelajari materi ini, peserta didik diharapkan mampu: (1) menyebutkan unsur-unsur lingkaran; (2) menghitung keliling lingkaran dengan rumus; (3) menghitung luas lingkaran dengan rumus; (4) menyelesaikan soal cerita yang berkaitan dengan lingkaran dalam kehidupan sehari-hari.$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $bq$Pengertian dan Unsur Lingkaran$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $bq$Lingkaran adalah bangun datar yang semua titik pada sisinya berjarak sama dari satu titik pusat. Unsur-unsur lingkaran yang perlu diketahui: titik pusat (tengah lingkaran), jari-jari atau radius (r) yaitu jarak dari titik pusat ke sisi lingkaran, diameter (d) yaitu garis lurus yang melalui titik pusat dan menghubungkan dua titik pada sisi lingkaran — panjang diameter sama dengan dua kali jari-jari (d = 2 × r).$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $bq$Keliling dan Luas Lingkaran$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $bq$Keliling lingkaran adalah panjang garis yang mengelilingi lingkaran. Rumusnya: K = 2 × π × r atau K = π × d. Nilai π (pi) adalah 22/7 jika jari-jari/diameter kelipatan 7, atau 3,14 untuk ukuran lainnya. Contoh: lingkaran dengan jari-jari 7 cm memiliki keliling K = 2 × 22/7 × 7 = 44 cm. Luas lingkaran adalah besar daerah di dalam lingkaran, dengan rumus L = π × r × r (atau πr²). Contoh: lingkaran berjari-jari 7 cm memiliki luas L = 22/7 × 7 × 7 = 154 cm²; tutup panci berdiameter 28 cm (r = 14 cm) memiliki luas L = 22/7 × 14 × 14 = 616 cm².$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $bq$Contoh Soal Cerita$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Sebuah jam dinding berbentuk lingkaran memiliki jari-jari 10 cm. Berapa kelilingnya? (K = 2 × 3,14 × 10 = 62,8 cm)$txt$, $txt$Taman berbentuk lingkaran berdiameter 14 m. Berapa luas taman tersebut? (r = 7 m; L = 22/7 × 7 × 7 = 154 m²)$txt$, $txt$Roda sepeda memiliki diameter 70 cm. Berapa keliling roda tersebut? (K = 22/7 × 70 = 220 cm)$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $bq$Latihan Soal$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$1. Sebutkan tiga unsur lingkaran beserta pengertiannya.$txt$, $txt$2. Hitung keliling lingkaran dengan jari-jari 14 cm.$txt$, $txt$3. Hitung luas lingkaran dengan diameter 20 cm.$txt$, $txt$4. Sebuah piring memiliki diameter 21 cm. Berapa luas piring tersebut?$txt$, $txt$5. Jelaskan perbedaan jari-jari dan diameter.$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $bq$Kunci Jawaban$bq$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$txt$1. Titik pusat (tengah lingkaran), jari-jari (jarak pusat ke sisi), diameter (garis lurus melalui pusat, d = 2r).$txt$, $txt$2. K = 2 × 22/7 × 14 = 88 cm.$txt$, $txt$3. r = 10 cm; L = 3,14 × 10 × 10 = 314 cm².$txt$, $txt$4. r = 10,5 cm; L = 22/7 × 10,5 × 10,5 = 346,5 cm².$txt$, $txt$5. Jari-jari setengah dari diameter; diameter dua kali jari-jari dan melalui titik pusat.$txt$])));
